    `115 -20,138 -14,147 0,149 20,156 42,174 71,178 113,190 156,193 205,180 242,170 261,158 320,117 320,113 277,109 320,53 320,47 268,38 243,28 220,25 193,28 166,39 133,45 96,49 72,66 53,82 34,89 0`,
    `89 12,106 16,115 30,118 46,129 65,146 91,155 122,164 154,165 184,148 216,141 248,131 316,107 316,100 244,99 316,70 316,59 262,51 225,40 204,32 181,34 155,40 128,45 99,46 85,58 62,65 28,75 16`,
    `107 21,128 26,143 42,150 57,157 75,165 102,171 132,175 156,174 181,158 208,138 225,114 315,99 315,94 251,102 315,88 315,83 259,83 222,68 205,57 180,54 153,59 126,72 102,84 84,90 73,80 60,83 35`,
    `113 22,134 28,148 44,155 59,166 77,177 103,187 135,195 161,196 185,185 211,163 230,155 315,130 315,108 255,119 315,105 315,91 264,88 239,92 222,77 201,68 180,67 153,72 127,83 99,91 78,83 64,86 35`,
    `103 18,125 23,140 37,151 52,164 68,179 94,190 126,196 152,197 180,188 207,162 229,134 316,119 316,115 259,123 316,110 316,101 263,102 226,86 214,72 193,67 171,68 145,76 121,85 100,89 80,76 63,77 34`
  ].map(s => s.split(/[\s,]+/).map(Number));

  const bellies = [
    [99,152,.95,1,0,1,.13],[68,174,.94,.94,10,.96,.21],
    [93,158,.94,.97,-2,1,.16],[109,180,1.35,1.36,0,1,.2],
    [99,157,1.09,1.1,0,1,.19],[112,150,.97,1,-48,.68,.8],
    [132,161,1.05,1.04,-52,.64,.88],[132,158,1.03,1.06,-55,.66,.91]
  ];
  const legPoses = [
    [98,231,1,1],[66,239,1,1],[101,229,1.1,1],[113,277,1.38,1.2],
    [100,244,1.12,1],[93,232,.78,1],[106,243,.96,1],[115,239,.73,1]
  ];
  const faces = [
    [100,18,1,1,89,36.7,1,112.4,37.6,.92,0],
    [76,43,1.03,.97,65.8,63.1,1.08,95.1,59.9,.77,1],
    [89,29,1.08,1.04,74.2,53.4,1.02,105.8,56.1,.91,1],
    [116,-22,1.41,1.37,91,10.6,1.12,132.7,9.4,1.14,1],
    [90,12,1.17,1.13,72,37.5,1.12,108.2,35.2,1,1],
    [100,21,1.06,1.03,85.3,37.7,.78,80.5,36.9,0,1],
    [104,22,1.09,1.04,87.4,39.7,.78,83,39.4,0,1],
    [99,18,1.12,1.08,78.3,39.8,.81,74,38.2,0,1]
  ];
  const smiles = [
    [91.5,47.3,115.4,49,2.9,2.2],[79.5,76.1,99,72.7,3.4,1.5],
    [78.3,66.9,99.2,68.3,5.4,1.45],[96.3,28.6,126.3,25.9,-4.8,2.05],
    [77.3,51.6,100,50.5,4.8,1.55],[80.5,57.3,86,60.9,1,1],
    [83,58.3,89.1,62.5,1,.92],[75.2,58,81.7,62,.8,1]
  ];

  // Shoulder, elbow and wrist positions, local radii, palm orientation and finger pose.
  const leftArms = [
    [64,72,49,121,35,185,12,7,4.8,14,.89,1.02,.15,0],
    [47,98,50,129,71,88,11.5,12.3,6.1,-126,1.13,.83,.3,1],
    [57,105,51,149,54,117,10.1,9.8,6.8,163,1.06,.92,.65,1],
    [65,77,46,141,8,200,16.5,10.6,7.5,63,1.25,.99,.24,0],
    [58,91,63,148,73,117,11.4,12.2,7.4,159,1.29,.97,1,1],
    [109,90,55,105,43,56,14.4,12.8,6.5,-159,1,.81,-.48,1],
    [118,98,59,116,38,78,15,13.3,6,158,.96,.79,-.35,1],
    [104,100,127,157,152,218,14,11.1,6.8,-30,1.03,.96,.56,1]
  ];
  const rightArms = [
    [121,66,138,105,157,192,10.5,6.6,5.2,-13,.91,.99,.08,0],
    [99,95,109,111,107,89,10,10.8,6,148,1.08,.85,.27,1],
    [119,89,153,134,170,128,10.7,10.5,5.8,-72,.95,.84,-.23,1],
    [158,75,169,142,187,207,14,8.7,5.5,-4,.78,.82,0,0],
    [132,74,147,132,161,203,11,7.3,5.4,-17,.88,1.02,.42,0],
    [96,89,57,108,29,90,10.6,8.3,5.2,113,.72,1.16,-.26,0],
    [106,97,63,119,29,98,11.3,8.7,5.6,111,.8,1.16,-.27,0],
    [112,94,121,148,135,199,10.8,7.8,5.3,-13,.83,.97,.2,0]
  ];

  const byId = id => document.getElementById(id);
  const attr = (el,key,value) => el.setAttribute(key,value);
  function make(tag,parent,attrs) {
    const el=document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(const [key,value] of Object.entries(attrs)) attr(el,key,value);
    parent.appendChild(el);
    return el;
  }
  function contourPath(points) {
    const count=points.length/2;
    const p=(i,k)=>points[((i+count)%count)*2+k];
    let d=`M${p(0,0)} ${p(0,1)}`;
    for(let i=0;i<count;i++){
      const j=i+1;
      const u=i===13 ? .018 : .158;
      const v=j===13 ? .018 : .158;
      const x1=p(i,0)+u*(p(j,0)-p(i-1,0));
      const y1=p(i,1)+u*(p(j,1)-p(i-1,1));
      const x2=p(j,0)-v*(p(j+1,0)-p(i,0));
      const y2=p(j,1)-v*(p(j+1,1)-p(i,1));
      d+=`C${x1} ${y1} ${x2} ${y2} ${p(j,0)} ${p(j,1)}`;
    }
    return d+"Z";
  }
  function makeArm(side) {
    const g=make("g",byId("arms-behind-torso"),{id:"arm-"+side,filter:"url(#soft-edge)"});
    const upper=make("g",g,{id:"upper-arm-"+side});
    const upperShape=make("path",upper,{fill:"url(#upper-arm-gold)"});
    const fore=make("g",g,{id:"forearm-"+side});
    const foreShape=make("path",fore,{fill:"url(#forearm-gold)"});
    const wrist=make("path",fore,{fill:"url(#wrist-color)"});
    const hand=make("g",g,{id:"hand-"+side});
    const fingers=make("g",hand,{id:"fingers-"+side});
    const silhouette=make("path",fingers,{fill:"url(#hand-color)"});
    const glint=make("path",hand,{d:"M-4.3 1.3 Q-5.8 5 -5.6 8.2",fill:"none",stroke:"#b79a58","stroke-width":1.4,opacity:".38"});
    const front=make("use",byId("arms-in-front"),{href:"#arm-"+side});
    return {upper,upperShape,fore,foreShape,wrist,hand,silhouette,front};
  }
  function limbSegment(group,shape,x,y,ex,ey,r,s,forearm) {
    const len=Math.max(.01,Math.hypot(ex-x,ey-y));
    const angle=Math.atan2(ey-y,ex-x)*180/Math.PI-90;
    attr(group,"transform",`translate(${x} ${y}) rotate(${angle})`);
    const mid=(r*.58+s*.42)*(forearm ? 1.08 : 1.03);
    const cap=forearm ? .64 : .86;
    attr(shape,"d",`M${-r} 0 C${-r} ${-r*cap*1.34} ${r} ${-r*cap*1.34} ${r} 0
      C${r*1.03} ${len*.22} ${mid} ${len*.66} ${s} ${len}
      C${s} ${len+s*1.15} ${-s} ${len+s*1.15} ${-s} ${len}
      C${-mid*1.03} ${len*.68} ${-r*1.07} ${len*.24} ${-r} 0Z`);
    return len;
  }
  function drawArm(a,p,angle,mirror) {
    const [sx,sy,ex,ey,wx,wy,r,e,w,,handWidth,handLength,spread,front]=p;
    limbSegment(a.upper,a.upperShape,sx,sy,ex,ey,r,e,false);
    const L=limbSegment(a.fore,a.foreShape,ex,ey,wx,wy,e,w,true);
    const start=L*.62;
    const q=e*.38+w*.62;
    attr(a.wrist,"d",`M${-q} ${start} Q${-w*1.14} ${L*.91} ${-w} ${L} Q0 ${L+w*1.35} ${w} ${L} Q${w*1.14} ${L*.91} ${q} ${start}Z`);
    attr(a.hand,"transform",`translate(${wx} ${wy}) rotate(${angle}) scale(${mirror*handWidth} ${handLength})`);
    const open=Math.max(0,spread), curl=Math.max(0,-spread);
    const wide=1+.3*open;
    let d="M-4.5 -2 Q-6.8 .5 -7.2 5.4";
    const thumbX=-8.7-11*open, thumbY=16.5-17*open-6*curl;
    d+=`Q-9.3 8.1 ${thumbX} ${thumbY} Q${thumbX-.7} ${thumbY+3.4} ${thumbX+2.1} ${thumbY+2.3} Q-6.5 13 -5.1 12.3`;
    const roots=[-5.2,-2,.98,4.05,6.95];
    const tips=[-6.6,-2.3,2.1,6.6];
    const lengths=[25.5,30,28.3,23.8];
    for(let f=0;f<4;f++){
      const tx=tips[f]*(1+open*1.35)*(1-curl*.42);
      const ty=lengths[f]-curl*(f===0 ? 22 : 25)-open*(f===3 ? 1 : 0);
      const end=roots[f+1]*wide;
      d+=`Q${tx-1.8} ${ty-5} ${tx-1.5} ${ty-.8} Q${tx-.4} ${ty+2.4} ${tx+1.2} ${ty} Q${tx+2.2} ${ty-1.4} ${end} ${f===3 ? 10 : 15.8-curl*6}`;
    }
    attr(a.silhouette,"d",d+"Q8 3.6 4.8 -1.8 Q0 -4 -4.5 -2Z");
    attr(a.front,"opacity",front);
  }
  function poseAt(t) {
    const ms=((t%duration)+duration)%duration;
    let k=0;
    while(k<times.length-1 && ms>=times[k+1]) k++;
    const next=Math.min(k+1,times.length-1);
    const f=next===k ? 0 : (ms-times[k])/(times[next]-times[k]);
    const z=f*f*(3-2*f);
    const get=seq=>seq[k].map((v,i)=>v+(seq[next][i]-v)*z);
    const angle=seq=>seq[k][9]+(((seq[next][9]-seq[k][9]+540)%360)-180)*z;
    return {get,angle};
  }
  function drawEye(side,x,y,size,open,profile) {
    const eye=byId("eye-"+side);
    attr(eye,"transform",`translate(${x} ${y}) scale(${size*(1-.43*profile)} ${size})`);
    const pupil=byId("eye-"+side+"-open");
    attr(pupil,"opacity",Math.min(1,open*1.23));
    attr(pupil,"transform",`scale(1 ${.09+.91*open})`);
  }
  let farArm,nearArm;
  function render(t) {
    if(!byId("surface-grain")) return;
    if(!farArm){
      farArm=makeArm("right");
      nearArm=makeArm("left");
    }
    const {get,angle}=poseAt(t);
    attr(byId("body-outline"),"d",contourPath(get(contours)));
    const [lx,ly,lsx,lsy]=get(legPoses);
    attr(byId("legs"),"transform",`translate(${lx} ${ly}) scale(${lsx} ${lsy})`);
    const [bx,by,bw,bh,offset,compression,orange]=get(bellies);
    attr(byId("rounded-belly"),"transform",`translate(${bx} ${by}) scale(${bw} ${bh})`);
    attr(byId("belly-front-light"),"transform",`translate(${offset} 0) scale(${compression} 1)`);
    const profile=Math.max(0,Math.min(1,-offset/48));
    attr(byId("shoulder-light"),"transform",`translate(${offset*.35} 0)`);
    attr(byId("flank-light"),"opacity",.82-profile*.58);
    attr(byId("flank-gold"),"opacity",orange);
    const [hx,hy,hw,hh,ax,ay,as,bex,bey,bs,open]=get(faces);
    attr(byId("head-modeling"),"transform",`translate(${hx} ${hy}) scale(${hw} ${hh})`);
    attr(byId("head-modeling"),"opacity",1-profile*.5);
    drawEye("left",ax,ay,as,open,profile);
    drawEye("right",bex,bey,bs,open,0);
    const [x,y,x2,y2,bend,thick]=get(smiles);
    const mid=(x+x2)/2, yc=(y+y2)/2+bend;
    attr(byId("muzzle-light"),"transform",`translate(${mid} ${(y+y2)/2-3.3}) scale(${(x2-x)/23} ${hh})`);
    attr(byId("lip-line"),"d",`M${x} ${y} Q${mid} ${yc} ${x2} ${y2} Q${mid+1} ${yc+thick*2} ${x} ${y+.45}Z`);
    attr(byId("lip-light"),"d",`M${x+1} ${y+2.1} Q${mid} ${yc+thick*2.4} ${x2-1} ${y2+1.65}`);
    attr(byId("lip-light"),"stroke-width",1.05*hh);
    drawArm(farArm,get(rightArms),angle(rightArms),-1);
    drawArm(nearArm,get(leftArms),angle(leftArms),1);
  }
  window.nwb={render};
  document.addEventListener("DOMContentLoaded",()=>render(0),{once:true});
})();
</script>
